  margin-bottom: 1rem;
}

.resource-card h3 {
  font-size: 1.0625rem;
  margin-bottom: 0.5rem;
  line-height: 1.4;
}

.resource-card p {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

@media (max-width: 768px) {
  .resources-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   FILE TYPE TAGS
   ============================================== */

.file-types-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

.file-type-tag {
  padding: 0.625rem 1.25rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
