    grid-template-columns: 1fr;
    gap: 1.5rem;
  }
}

/* ==============================================
   PRODUCT CARDS
   ============================================== */

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

.product-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
