  background: var(--color-accent);
  border-radius: 50%;
  flex-shrink: 0;
}

@media (max-width: 768px) {
  .split-section,
  .split-section.reverse .split-visual {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .split-section.reverse .split-visual {
    order: 0;
  }
}

/* ==============================================
   INTEGRATIONS GRID
   ============================================== */

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}

.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem 1rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-gray-600);
  transition: all 0.3s ease;
}

.integration-item:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
  color: var(--color-primary);
}

@media (max-width: 900px) {
  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 560px) {
  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ==============================================
   TESTIMONIALS CAROUSEL
   ============================================== */

.testimonials-section {
  position: relative;
}

.testimonials-carousel {
  overflow: hidden;
  position: relative;
}

.testimonials-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 calc(33.333% - 1.333rem);
  margin-right: 1.5rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
}

.testimonial-card:hover {
  box-shadow: var(--shadow-lg);
}

.testimonial-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
  color: var(--color-burgundy);
  flex-shrink: 0;
}

.testimonial-meta h4 {
  font-size: 0.9375rem;
  margin-bottom: 0.125rem;
}

.testimonial-meta span {
  font-size: 0.8125rem;
  color: var(--color-gray-500);
}

.testimonial-badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 100px;
  margin-bottom: 0.75rem;
}

.testimonial-text {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.7;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--color-gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-gray-700);
  transition: all 0.2s ease;
}

.carousel-btn:hover {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  transition: all 0.3s ease;
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: 4px;
}

@media (max-width: 900px) {
  .testimonial-card {
    flex: 0 0 calc(100% - 1rem);
  }
}

/* ==============================================
   PRICING
   ============================================== */

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

.pricing-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
  position: relative;
}

.pricing-card.featured {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-xl);
  background: var(--color-primary);
  color: var(--color-white);
  transform: scale(1.03);
}

.pricing-card.featured h3,
.pricing-card.featured .pricing-amount,
.pricing-card.featured .pricing-period {
  color: var(--color-white);
}

.pricing-card:hover {
  box-shadow: var(--shadow-xl);
}

.pricing-card.featured:hover {
  box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25);
}

.pricing-popular {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 100px;
  margin-bottom: 1rem;
}

.pricing-card h3 {
  margin-bottom: 0.75rem;
}

.pricing-amount {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-primary);
}

.pricing-period {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  margin-bottom: 1.5rem;
}

.pricing-card.featured .pricing-period {
  color: var(--color-gray-400);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  margin-bottom: 1.5rem;
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-size: 0.875rem;
  color: var(--color-gray-600);
}

.pricing-card.featured .pricing-feature {
  color: var(--color-gray-300);
}

.pricing-check {
  color: #22c55e;
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card.featured .btn-primary {
  background: var(--color-accent);
}

@media (max-width: 1000px) {
  .pricing-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 560px) {
  .pricing-grid {
    grid-template-columns: 1fr;
  }
  .pricing-card.featured {
    transform: none;
  }
}

/* Enterprise section */
.enterprise-card {
  background: linear-gradient(135deg, var(--color-primary) 0%, #1a1a2e 100%);
  border-radius: var(--radius-xl);
  padding: 3rem;
  color: var(--color-white);
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2rem;
  align-items: center;
  margin-top: 2rem;
}

.enterprise-card h3 {
  color: var(--color-white);
  margin-bottom: 0.75rem;
}

.enterprise-card p {
  color: var(--color-gray-400);
  line-height: 1.7;
}

.enterprise-features {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-top: 1rem;
}

.enterprise-feature {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  color: var(--color-gray-300);
}

@media (max-width: 768px) {
  .enterprise-card {
    grid-template-columns: 1fr;
    padding: 2rem;
  }
}

/* ==============================================
   SOCIAL PROOF
   ============================================== */

.social-proof-section {
  background: var(--color-gray-50);
}

.social-proof-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.social-proof-item {
  padding: 1.5rem;
}

.social-proof-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.social-proof-value {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  color: var(--color-primary);
  margin-bottom: 0.5rem;
}

.social-proof-label {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
}

@media (max-width: 768px) {
  .social-proof-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .social-proof-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   FAQ ACCORDION
   ============================================== */

.faq-list {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.faq-item {
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color 0.3s ease;
}

.faq-item.open {
  border-color: var(--color-accent);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-primary);
  text-align: left;
  transition: background 0.2s ease;
}

.faq-question:hover {
  background: var(--color-gray-50);
}

.faq-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: transform 0.3s ease;
  color: var(--color-gray-400);
}

.faq-item.open .faq-icon {
  transform: rotate(45deg);
  color: var(--color-primary);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding: 0 1.5rem 1.25rem;
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.7;
}

/* ==============================================
   CTA BANNER
   ============================================== */

.cta-banner {
  background: var(--color-primary);
  padding: 4.5rem 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, -40%);
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.08) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.cta-banner-inner {
  position: relative;
  z-index: 1;
}

.cta-banner h2 {
  color: var(--color-white);
  margin-bottom: 1rem;
  font-size: clamp(2rem, 3.5vw, 2.75rem);
}

.cta-banner p {
  color: var(--color-gray-400);
  font-size: 1.125rem;
  margin-bottom: 2rem;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ==============================================
   FOOTER
   ============================================== */

.footer {
  background: var(--color-gray-50);
  border-top: 1px solid var(--color-gray-200);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  margin-top: 1rem;
  line-height: 1.7;
}

.footer-col h4 {
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-gray-500);
  margin-bottom: 1.25rem;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-link {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  transition: color 0.2s ease;
}

.footer-link:hover {
  color: var(--color-primary);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 2rem;
  border-top: 1px solid var(--color-gray-200);
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

.footer-social {
  display: flex;
  gap: 1rem;
}

.footer-social-link {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  color: var(--color-gray-600);
  transition: all 0.2s ease;
}

.footer-social-link:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

@media (max-width: 900px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 560px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .footer-bottom {
    flex-direction: column;
    gap: 1rem;
  }
}

/* ==============================================
   FEATURE CARDS (3-COLUMN)
   ============================================== */

.feature-cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.feature-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
}

.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-color: var(--color-accent);
}

.feature-card-icon {
  width: 48px;
  height: 48px;
  background: var(--color-gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.375rem;
}

.feature-card:hover .feature-card-icon {
  background: var(--color-accent);
}

.feature-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
}

.feature-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.7;
}

@media (max-width: 768px) {
  .feature-cards-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   TOOLS GRID
   ============================================== */

.tools-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.tool-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 1.25rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  transition: all 0.2s ease;
}

.tool-item:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-sm);
}

.tool-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-accent);
  flex-shrink: 0;
}

@media (max-width: 768px) {
  .tools-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .tools-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   STEPS (COACHING 3-STEP)
   ============================================== */

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  position: relative;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-accent);
  color: var(--color-primary);
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
}

.step-card h3 {
  margin-bottom: 0.5rem;
}

.step-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

@media (max-width: 768px) {
  .steps-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}

/* ==============================================
   RESOURCE CARDS
   ============================================== */

.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.resource-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.resource-card-icon {
  font-size: 1.75rem;
  margin-bottom: 1rem;
}

.resource-card h3 {
  font-size: 1.0625rem;
  margin-bottom: 0.5rem;
  line-height: 1.4;
}

.resource-card p {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

@media (max-width: 768px) {
  .resources-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   FILE TYPE TAGS
   ============================================== */

.file-types-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

.file-type-tag {
  padding: 0.625rem 1.25rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: 100px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  transition: all 0.2s ease;
}

.file-type-tag:hover {
  border-color: var(--color-accent);
  background: var(--color-gray-50);
}

/* ==============================================
   COACHING SPOTLIGHT CARDS
   ============================================== */

.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.spotlight-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  transition: all 0.3s ease;
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.spotlight-avatar {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--color-gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-burgundy);
}

.spotlight-card h3 {
  font-size: 1.0625rem;
  margin-bottom: 0.5rem;
}

.spotlight-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
}

@media (max-width: 768px) {
  .spotlight-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   PRODUCT DEMO ACCORDION
   ============================================== */

.demo-section {
  max-width: 900px;
  margin: 0 auto;
}

.demo-toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 1.25rem 2rem;
  background: var(--color-primary);
  color: var(--color-white);
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-weight: 600;
  transition: all 0.3s ease;
}

.demo-toggle:hover {
  background: var(--color-primary-light);
}

.demo-toggle-icon {
  transition: transform 0.3s ease;
}

.demo-toggle.open .demo-toggle-icon {
  transform: rotate(180deg);
}

.demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.5s ease;
  border: 1px solid var(--color-gray-200);
  border-top: 0;
  border-radius: 0 0 var(--radius-md) var(--radius-md);
}

.demo-content.open {
  max-height: 600px;
}

.demo-content-inner {
  padding: 2rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.demo-card {
  padding: 1.5rem;
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  text-align: center;
}

.demo-card-icon {
  font-size: 2rem;
  margin-bottom: 0.75rem;
}

.demo-card h4 {
  font-size: 0.9375rem;
  margin-bottom: 0.375rem;
}

.demo-card p {
  font-size: 0.8125rem;
  color: var(--color-gray-500);
}

@media (max-width: 768px) {
  .demo-content-inner {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   ANIMATIONS
   ============================================== */

.fade-up {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

.fade-in {
  opacity: 0;
  transition: opacity 0.6s ease;
}

.fade-in.visible {
  opacity: 1;
}

/* Stagger children */
.stagger-children > * {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.stagger-children.visible > *:nth-child(1) { transition-delay: 0s; }
.stagger-children.visible > *:nth-child(2) { transition-delay: 0.1s; }
.stagger-children.visible > *:nth-child(3) { transition-delay: 0.2s; }
.stagger-children.visible > *:nth-child(4) { transition-delay: 0.3s; }
.stagger-children.visible > *:nth-child(5) { transition-delay: 0.4s; }
.stagger-children.visible > *:nth-child(6) { transition-delay: 0.5s; }

.stagger-children.visible > * {
  opacity: 1;
  transform: translateY(0);
}

/* ==============================================
   SECTION BACKGROUNDS
   ============================================== */

.bg-dark {
  background: var(--color-primary);
  color: var(--color-white);
}

.bg-dark .section-title,
.bg-dark h2,
.bg-dark h3 {
  color: var(--color-white);
}

.bg-dark .section-subtitle,
.bg-dark p {
  color: var(--color-gray-400);
}

.bg-warm {
  background: var(--color-gray-50);
}

.bg-accent-light {
  background: #fdfde8;
}

/* ==============================================
   UTILITY
   ============================================== */

.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }
.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }

/* ==============================================
   VALUE PROPOSITION (3-col with icons)
   ============================================== */

.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.value-card {
  text-align: center;
  padding: 2.5rem 2rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  transition: all 0.3s ease;
}

.value-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.value-icon {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}

.value-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.75rem;
}

.value-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

@media (max-width: 768px) {
  .value-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   BG ACCENT SECTION
   ============================================== */

.bg-accent-section {
  background: linear-gradient(180deg, #fefec8 0%, #fdfde8 100%);
}

/* Business-fit section */
.business-fit-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

.business-fit-card {
  text-align: center;
  padding: 2rem;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-gray-200);
  transition: all 0.3s ease;
}

.business-fit-card:hover {
  box-shadow: var(--shadow-lg);
}

.business-fit-icon {
  font-size: 2rem;
  margin-bottom: 0.75rem;
}

.business-fit-card h4 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.business-fit-card p {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

@media (max-width: 900px) {
  .business-fit-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .business-fit-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   CREATE & SELL SECTION
   ============================================== */

.create-sell-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.create-sell-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  transition: all 0.3s ease;
}

.create-sell-card:hover {
  box-shadow: var(--shadow-lg);
}

.create-sell-card h3 {
  margin-bottom: 1rem;
}

.create-sell-card ul {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.create-sell-card li {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-size: 0.9375rem;
  color: var(--color-gray-600);
}

.create-sell-check {
  color: #22c55e;
  font-weight: 700;
  flex-shrink: 0;
}

@media (max-width: 768px) {
  .create-sell-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   MEMBERSHIP STATS
   ============================================== */

.membership-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.membership-stat-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  transition: all 0.3s ease;
}

.membership-stat-card:hover {
  box-shadow: var(--shadow-lg);
}

.membership-stat-value {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-burgundy);
  margin-bottom: 0.5rem;
}

.membership-stat-label {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.5;
}

@media (max-width: 768px) {
  .membership-stats {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   MANAGEMENT FEATURES (Memberships page)
   ============================================== */

.management-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.management-card {
  text-align: center;
  padding: 2rem;
}

.management-icon {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}

.management-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.75rem;
}

.management-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

@media (max-width: 768px) {
  .management-grid {
    grid-template-columns: 1fr;
  }
}
