/* ==============================================
   LearnForge — Design System
   Brand: #000000 (primary), #E6FF32 (accent), #7F2A23 (burgundy)
   ============================================== */

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

:root {
  --font-heading: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;

  --color-primary: #0a0a0f;
  --color-primary-light: #1a1a24;
  --color-accent: #E6FF32;
  --color-accent-hover: #d4f01a;
  --color-accent-dark: #b8d420;
  --color-burgundy: #7F2A23;
  --color-burgundy-light: #9a3a32;
  --color-white: #ffffff;
  --color-off-white: #f8f9fb;
  --color-gray-50: #f9fafb;
  --color-gray-100: #f3f4f6;
  --color-gray-200: #e5e7eb;
  --color-gray-300: #d1d5db;
  --color-gray-400: #9ca3af;
  --color-gray-500: #6b7280;
  --color-gray-600: #4b5563;
  --color-gray-700: #374151;
  --color-gray-800: #1f2937;
  --color-gray-900: #111827;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.05);
  --shadow-card: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  --max-width: 1200px;
  --nav-height: 72px;
}

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background: var(--color-white);
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* ==============================================
   TYPOGRAPHY
   ============================================== */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  color: var(--color-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 3.5vw, 3rem); letter-spacing: -0.015em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.75rem); }
h4 { font-size: 1.125rem; }

.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-burgundy);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--color-gray-500);
  max-width: 600px;
  line-height: 1.7;
}

.text-center { text-align: center; }
.text-accent { color: var(--color-accent); }
.text-burgundy { color: var(--color-burgundy); }

/* ==============================================
   CONTAINERS & LAYOUT
   ============================================== */

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

.section {
  padding: 5rem 0;
}

.section-header {
  text-align: center;
  margin-bottom: 3.5rem;
}

.section-header .section-subtitle {
  margin: 0 auto;
}

/* ==============================================
   NAVIGATION
   ============================================== */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--nav-height);
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-gray-100);
  transition: box-shadow 0.3s ease;
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  transition: color 0.2s ease;
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-accent);
  border-radius: 1px;
}

.nav-cta {
  display: inline-flex;
  align-items: center;
  padding: 0.625rem 1.5rem;
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 0.875rem;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: background 0.2s ease, transform 0.2s ease;
}

.nav-cta:hover {
  background: var(--color-accent-hover);
  transform: translateY(-1px);
}

.nav-mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
  z-index: 1001;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 2px;
  transition: transform 0.3s ease, opacity 0.3s ease;
}

.nav-mobile-toggle.open span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-mobile-toggle.open span:nth-child(2) {
  opacity: 0;
}
.nav-mobile-toggle.open span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* Mobile nav */
@media (max-width: 900px) {
  .nav-links {
    position: fixed;
    top: 0;
    right: -100%;
    width: 280px;
    height: 100vh;
    background: var(--color-white);
    flex-direction: column;
    padding: 6rem 2rem 2rem;
    gap: 1.5rem;
    box-shadow: var(--shadow-xl);
    transition: right 0.3s ease;
  }

  .nav-links.open {
    right: 0;
  }

  .nav-mobile-toggle {
    display: flex;
  }

  .nav-mobile-overlay {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.3);
    z-index: 999;
  }

  .nav-mobile-overlay.open {
    display: block;
  }
}

/* ==============================================
   BUTTONS
   ============================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-size: 1rem;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: all 0.2s ease;
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-primary);
}

.btn-primary:hover {
  background: var(--color-accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(230,255,50,0.4);
}

.btn-secondary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-secondary:hover {
  background: var(--color-primary-light);
  transform: translateY(-2px);
}

.btn-outline {
  border: 2px solid var(--color-gray-300);
  color: var(--color-primary);
  background: transparent;
}

.btn-outline:hover {
  border-color: var(--color-primary);
  background: var(--color-gray-50);
}

.btn-burgundy {
  background: var(--color-burgundy);
  color: var(--color-white);
}

.btn-burgundy:hover {
  background: var(--color-burgundy-light);
  transform: translateY(-2px);
}

.btn-lg {
  padding: 1rem 2.5rem;
  font-size: 1.0625rem;
}

.btn-group {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* ==============================================
   HERO SECTIONS
   ============================================== */

.hero {
  padding: calc(var(--nav-height) + 4rem) 0 5rem;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(230,255,50,0.08) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(127,42,35,0.04) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  position: relative;
  z-index: 1;
}

.hero-content {
  max-width: 560px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 0.875rem;
  background: var(--color-gray-100);
  border-radius: 100px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-gray-700);
  margin-bottom: 1.5rem;
}

.hero-badge-dot {
  width: 6px;
  height: 6px;
  background: #22c55e;
  border-radius: 50%;
  animation: pulse-dot 2s infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.hero-title {
  font-size: clamp(2.5rem, 5vw, 3.75rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.025em;
  margin-bottom: 1.25rem;
}

.hero-title .highlight {
  background: linear-gradient(120deg, var(--color-accent) 0%, var(--color-accent) 100%);
  background-size: 100% 35%;
  background-position: 0 80%;
  background-repeat: no-repeat;
  padding: 0 0.1em;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--color-gray-500);
  line-height: 1.7;
  margin-bottom: 2rem;
  max-width: 480px;
}

.hero-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-preview {
  width: 100%;
  max-width: 540px;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
}

.hero-preview-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background: var(--color-gray-50);
  border-bottom: 1px solid var(--color-gray-200);
}

.hero-preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.hero-preview-dot:nth-child(1) { background: #ef4444; }
.hero-preview-dot:nth-child(2) { background: #f59e0b; }
.hero-preview-dot:nth-child(3) { background: #22c55e; }

.hero-preview-body {
  padding: 2rem;
}

.hero-preview-placeholder {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.hero-preview-line {
  height: 10px;
  background: var(--color-gray-100);
  border-radius: 5px;
}

.hero-preview-line:nth-child(1) { width: 60%; }
.hero-preview-line:nth-child(2) { width: 100%; }
.hero-preview-line:nth-child(3) { width: 80%; }
.hero-preview-line:nth-child(4) { width: 40%; }

/* Home hero tab switch */
.hero-tabs {
  display: inline-flex;
  background: var(--color-gray-100);
  border-radius: var(--radius-sm);
  padding: 0.25rem;
  margin-bottom: 2rem;
}

.hero-tab {
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-gray-600);
  border-radius: 6px;
  transition: all 0.3s ease;
  cursor: pointer;
}

.hero-tab.active {
  background: var(--color-white);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

@media (max-width: 768px) {
  .hero-inner {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }
  .hero-content {
    order: -1;
  }
  .hero-visual {
    order: 0;
  }
  .hero-preview {
    max-width: 100%;
  }
  .hero {
    padding: calc(var(--nav-height) + 2rem) 0 3rem;
  }
}

/* ==============================================
   STATS BAR
   ============================================== */

.stats-bar {
  background: var(--color-primary);
  padding: 2.5rem 0;
  position: relative;
  overflow: hidden;
}

.stats-bar::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 20% 50%, rgba(230,255,50,0.06) 0%, transparent 60%);
  pointer-events: none;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  text-align: center;
  position: relative;
  z-index: 1;
}

.stat-item {
  padding: 0.5rem;
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--color-gray-400);
  font-weight: 500;
}

@media (max-width: 640px) {
  .stats-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }
}

/* ==============================================
   PRODUCT CARDS
   ============================================== */

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

.product-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
  cursor: pointer;
  position: relative;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
  border-color: var(--color-accent);
}

.product-card-icon {
  width: 48px;
  height: 48px;
  background: var(--color-gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.5rem;
  transition: background 0.3s ease;
}

.product-card:hover .product-card-icon {
  background: var(--color-accent);
}

.product-card h3 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.product-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

@media (max-width: 900px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 560px) {
  .products-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   TABBED FEATURES (Why Choose Us)
   ============================================== */

.features-tabs {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 3rem;
  flex-wrap: wrap;
  justify-content: center;
}

.feature-tab {
  padding: 0.75rem 1.5rem;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-gray-600);
  border-radius: var(--radius-sm);
  transition: all 0.3s ease;
  border: 1px solid transparent;
  white-space: nowrap;
}

.feature-tab:hover {
  color: var(--color-primary);
  background: var(--color-gray-50);
}

.feature-tab.active {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.features-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.features-list {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
}

.feature-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.75rem;
  font-size: 0.9375rem;
  color: var(--color-gray-700);
}

.feature-item-check {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  background: var(--color-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  margin-top: 2px;
  color: var(--color-primary);
}

.features-visual {
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: 2rem;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (max-width: 768px) {
  .features-content {
    grid-template-columns: 1fr;
  }
  .features-tabs {
    flex-direction: column;
    align-items: stretch;
  }
  .feature-tab {
    text-align: center;
  }
}

/* ==============================================
   GLOBAL SCALE / AI SECTIONS
   ============================================== */

.split-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.split-section.reverse .split-visual {
  order: -1;
}

.split-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}

.split-visual-placeholder {
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/3;
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-gray-200);
  font-size: 4rem;
  color: var(--color-gray-300);
}

.split-content h2 {
  margin-bottom: 1.25rem;
}

.split-content p {
  color: var(--color-gray-500);
  margin-bottom: 1rem;
  line-height: 1.7;
}

.split-bullets {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.split-bullet {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.9375rem;
  color: var(--color-gray-700);
}

.split-bullet-dot {
  width: 8px;
  height: 8px;
  background: var(--color-accent);
  border-radius: 50%;
  flex-shrink: 0;
}

@media (max-width: 768px) {
  .split-section,
  .split-section.reverse .split-visual {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .split-section.reverse .split-visual {
    order: 0;
  }
}

/* ==============================================
   INTEGRATIONS GRID
   ============================================== */

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}

.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem 1rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-gray-600);
  transition: all 0.3s ease;
}

.integration-item:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
  color: var(--color-primary);
}

@media (max-width: 900px) {
  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 560px) {
  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ==============================================
   TESTIMONIALS CAROUSEL
   ============================================== */

.testimonials-section {
  position: relative;
}

.testimonials-carousel {
  overflow: hidden;
  position: relative;
}

.testimonials-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 calc(33.333% - 1.333rem);
  margin-right: 1.5rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
}

.testimonial-card:hover {
  box-shadow: var(--shadow-lg);
}

.testimonial-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
  color: var(--color-burgundy);
  flex-shrink: 0;
}

.testimonial-meta h4 {
  font-size: 0.9375rem;
  margin-bottom: 0.125rem;
}

.testimonial-meta span {
  font-size: 0.8125rem;
  color: var(--color-gray-500);
}

.testimonial-badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 100px;
  margin-bottom: 0.75rem;
}

.testimonial-text {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.7;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--color-gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-gray-700);
  transition: all 0.2s ease;
}

.carousel-btn:hover {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  transition: all 0.3s ease;
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: 4px;
}

@media (max-width: 900px) {
  .testimonial-card {
    flex: 0 0 calc(100% - 1rem);
  }
}

/* ==============================================
   PRICING
   ============================================== */

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

.pricing-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
  position: relative;
}

.pricing-card.featured {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-xl);
  background: var(--color-primary);
  color: var(--color-white);
  transform: scale(1.03);
}

.pricing-card.featured h3,
.pricing-card.featured .pricing-amount,
.pricing-card.featured .pricing-period {
  color: var(--color-white);
}

.pricing-card:hover {
  box-shadow: var(--shadow-xl);
}

.pricing-card.featured:hover {
  box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25);
}

.pricing-popular {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 100px;
  margin-bottom: 1rem;
}

.pricing-card h3 {
  margin-bottom: 0.75rem;
}

.pricing-amount {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-primary);
}

.pricing-period {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  margin-bottom: 1.5rem;
}

.pricing-card.featured .pricing-period {
  color: var(--color-gray-400);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  margin-bottom: 1.5rem;
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-size: 0.875rem;
  color: var(--color-gray-600);
}

.pricing-card.featured .pricing-feature {
  color: var(--color-gray-300);
}

.pricing-check {
  color: #22c55e;
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card.featured .btn-primary {
  background: var(--color-accent);
}

@media (max-width: 1000px) {
  .pricing-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 560px) {
  .pricing-grid {
    grid-template-columns: 1fr;
  }
  .pricing-card.featured {
    transform: none;
  }
}

/* Enterprise section */
.enterprise-card {
  background: linear-gradient(135deg, var(--color-primary) 0%, #1a1a2e 100%);
  border-radius: var(--radius-xl);
  padding: 3rem;
  color: var(--color-white);
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2rem;
  align-items: center;
  margin-top: 2rem;
}

.enterprise-card h3 {
  color: var(--color-white);
  margin-bottom: 0.75rem;
}

.enterprise-card p {
  color: var(--color-gray-400);
  line-height: 1.7;
}

.enterprise-features {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-top: 1rem;
}

.enterprise-feature {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  color: var(--color-gray-300);
}

@media (max-width: 768px) {
  .enterprise-card {
    grid-template-columns: 1fr;
    padding: 2rem;
  }
}

/* ==============================================
   SOCIAL PROOF
   ============================================== */

.social-proof-section {
  background: var(--color-gray-50);
}

.social-proof-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.social-proof-item {
  padding: 1.5rem;
}

.social-proof-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.social-proof-value {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  color: var(--color-primary);
  margin-bottom: 0.5rem;
}

.social-proof-label {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
}

@media (max-width: 768px) {
  .social-proof-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .social-proof-grid {
    grid-template-columns: 1fr;
  }
}

/* ==============================================
   FAQ ACCORDION
   ============================================== */

.faq-list {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.faq-item {
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color 0.3s ease;
}

.faq-item.open {
  border-color: var(--color-accent);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-primary);
  text-align: left;
  transition: background 0.2s ease;
}

.faq-question:hover {
  background: var(--color-gray-50);
}

.faq-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: transform 0.3s ease;
  color: var(--color-gray-400);
}

.faq-item.open .faq-icon {
  transform: rotate(45deg);
  color: var(--color-primary);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding: 0 1.5rem 1.25rem;
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.7;
}

/* ==============================================
   CTA BANNER
   ============================================== */

.cta-banner {
  background: var(--color-primary);
  padding: 4.5rem 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, -40%);
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.08) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.cta-banner-inner {
  position: relative;
  z-index: 1;
}

.cta-banner h2 {
  color: var(--color-white);
  margin-bottom: 1rem;
  font-size: clamp(2rem, 3.5vw, 2.75rem);
}

.cta-banner p {
  color: var(--color-gray-400);
  font-size: 1.125rem;
  margin-bottom: 2rem;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

/* ==============================================
   FOOTER
   ============================================== */

.footer {
  background: var(--color-gray-50);
  border-top: 1px solid var(--color-gray-200);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  margin-top: 1rem;
  line-height: 1.7;
}

.footer-col h4 {
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-gray-500);
  margin-bottom: 1.25rem;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-link {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  transition: color 0.2s ease;
}

.footer-link:hover {
  color: var(--color-primary);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 2rem;
  border-top: 1px solid var(--color-gray-200);
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

.footer-social {
  display: flex;
  gap: 1rem;
}

.footer-social-link {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  color: var(--color-gray-600);
  transition: all 0.2s ease;
}

.footer-social-link:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

@media (max-width: 900px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 560px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .footer-bottom {
    flex-direction: column;
    gap: 1rem;
  }
}

/* ==============================================
   FEATURE CARDS (3-COLUMN)
   ============================================== */

.feature-cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.feature-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s ease;
}

.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-color: var(--color-accent);
}

.feature-card-icon {
  width: 48px;
  height: 48px;
  background: var(--color-gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.375rem;
}

.feature-card:hover .feature-card-icon {
  background: var(--color-accent);
}

.feature-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
}

